/**
 * Validate that a date string is in YYYY-MM-DD format and represents a valid date (UTC).
 * @param {string} dateStr
 * @returns {boolean}
 */
export function isValidDate(dateStr) {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(dateStr)) return false;
  const date = new Date(dateStr + 'T00:00:00Z');
  if (Number.isNaN(date.getTime())) return false;
  const [year, month, day] = dateStr.split('-');
  return (
    date.getUTCFullYear() === Number(year) &&
    date.getUTCMonth() === Number(month) - 1 &&
    date.getUTCDate() === Number(day)
  );
}

/**
 * Add n days to a date (UTC arithmetic).
 * @param {string} date in YYYY-MM-DD format
 * @param {number} n number of days to add (can be negative)
 * @returns {string} result in YYYY-MM-DD format
 */
export function addDays(date, n) {
  const [year, month, day] = date.split('-').map(Number);
  const d = new Date(Date.UTC(year, month - 1, day));
  d.setUTCDate(d.getUTCDate() + n);
  const y = d.getUTCFullYear();
  const m = String(d.getUTCMonth() + 1).padStart(2, '0');
  const da = String(d.getUTCDate()).padStart(2, '0');
  return `${y}-${m}-${da}`;
}

/**
 * Calculate the number of whole days between two dates (b minus a, UTC).
 * @param {string} a start date in YYYY-MM-DD format
 * @param {string} b end date in YYYY-MM-DD format
 * @returns {number} whole days (b - a)
 */
export function daysBetween(a, b) {
  const [ya, ma, da] = a.split('-').map(Number);
  const [yb, mb, db] = b.split('-').map(Number);
  const dateA = new Date(Date.UTC(ya, ma - 1, da));
  const dateB = new Date(Date.UTC(yb, mb - 1, db));
  const diffMs = dateB.getTime() - dateA.getTime();
  return Math.floor(diffMs / 86400000);
}

